<template>
  <div class="app-shell">
    <header class="topbar"><BrandLogo compact /><nav><RouterLink class="active" to="/">秒杀广场</RouterLink><RouterLink to="/orders">我的订单</RouterLink></nav><div class="user-area"><span class="avatar">{{ userInitial }}</span><span>{{ user.username || '用户' }}</span><button type="button" @click="handleLogout">退出</button></div></header>
    <main class="content">
      <section class="hero-card"><div><p>SECKILLCORE</p><h1>限时好物，即刻开抢</h1><span>精选商品限时直降，提前锁定你的心仪好物。</span></div><div class="hero-mark">⚡</div></section>
      <section class="toolbar"><div class="section-title"><h2>秒杀广场</h2><p>实时更新热门活动</p></div><div class="search-box"><svg viewBox="0 0 24 24" fill="none"><circle cx="11" cy="11" r="6.5" stroke="currentColor" stroke-width="1.7"/><path d="m16 16 4.5 4.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg><input v-model.trim="keyword" placeholder="搜索商品" @keyup.enter="loadAll"><button v-if="keyword" type="button" @click="keyword = ''; loadAll()">清除</button></div></section>
      <div class="filter-row"><button :class="{ selected: activityFilter === 'all' }" type="button" @click="setFilter('all')">全部商品</button><button :class="{ selected: activityFilter === 'active' }" type="button" @click="setFilter('active')">正在进行</button><button :class="{ selected: activityFilter === 'soon' }" type="button" @click="setFilter('soon')">即将开始</button><button class="refresh-button" type="button" :disabled="loading" @click="loadAll"><svg viewBox="0 0 24 24" fill="none"><path d="M20 11a8 8 0 0 0-14.8-4M4 5v4h4M4 13a8 8 0 0 0 14.8 4M20 19v-4h-4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>刷新</button></div>
      <p v-if="errorMessage" class="page-error">{{ errorMessage }} <button type="button" @click="loadAll">重新加载</button></p>
      <div v-if="loading" class="product-grid"><div v-for="n in 4" :key="n" class="product-card skeleton"><div class="skeleton-image"></div><div class="skeleton-line wide"></div><div class="skeleton-line"></div></div></div>
      <div v-else-if="visibleProducts.length" class="product-grid"><article v-for="item in visibleProducts" :key="item.product.id" class="product-card" @click="openProduct(item)"><div class="product-image"><img v-if="item.product.imageUrl" :src="item.product.imageUrl" :alt="item.product.productName"><span v-else>⚡</span><span v-if="item.activity" class="activity-badge">{{ activityLabel(item.activity) }}</span></div><div class="product-body"><h3>{{ item.product.productName }}</h3><p>{{ item.product.description || '限时精选商品，数量有限' }}</p><div class="price-row"><strong>¥{{ formatPrice(item.activity?.seckillPrice || item.product.seckillPrice || item.product.price) }}</strong><del v-if="item.product.price">¥{{ formatPrice(item.product.price) }}</del><span class="stock">余 {{ item.activity?.remainingLimit ?? item.product.availableStock ?? '--' }}</span></div><button type="button" @click.stop="openProduct(item)">{{ actionText(item.activity) }}<svg viewBox="0 0 24 24" fill="none"><path d="m9 18 6-6-6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div></article></div>
      <div v-else class="empty-card"><div class="empty-icon">🛍️</div><h3>{{ keyword ? '没有找到相关商品' : '商品列表即将上线' }}</h3><p>{{ keyword ? '换个关键词试试吧。' : '活动商品准备中，请稍后再来看看。' }}</p></div>
    </main>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import BrandLogo from '../components/BrandLogo.vue'
import { getActivities } from '../api/activity'
import { getProducts } from '../api/product'
import { logout } from '../api/auth'
import { clearSession, getCurrentUser } from '../utils/auth'

const router = useRouter(); const user = getCurrentUser(); const userInitial = computed(() => (user.username || 'U').slice(0, 1).toUpperCase())
const products = ref([]); const activities = ref([]); const loading = ref(false); const keyword = ref(''); const activityFilter = ref('all'); const errorMessage = ref('')
const visibleProducts = computed(() => products.value.map((product) => ({ product, activity: activities.value.find((activity) => activity.productId === product.id) })).filter((item) => { if (activityFilter.value === 'active') return item.activity?.status === 1; if (activityFilter.value === 'soon') return item.activity?.status === 0; return true }))
function unwrapPage(result) { return result?.data?.records || result?.data?.list || [] }
function formatPrice(value) { return Number(value || 0).toFixed(2) }
function activityLabel(activity) { return activity?.status === 1 ? '进行中' : activity?.status === 0 ? '即将开始' : '已结束' }
function actionText(activity) { return activity?.status === 1 ? '立即抢购' : activity?.status === 0 ? '查看详情' : '查看商品' }
function setFilter(filter) { activityFilter.value = filter }
async function loadAll() { loading.value = true; errorMessage.value = ''; try { const [productResult, activityResult] = await Promise.all([getProducts({ page: 1, size: 20, keyword: keyword.value || undefined, status: 1 }), getActivities({ page: 1, size: 20 })]); products.value = unwrapPage(productResult); activities.value = unwrapPage(activityResult) } catch (error) { errorMessage.value = error.message } finally { loading.value = false } }
function openProduct(item) { router.push({ name: 'product-detail', params: { id: item.product.id }, query: item.activity ? { activityId: item.activity.id } : undefined }) }
async function handleLogout() { try { await logout() } catch {} clearSession(); await router.replace('/login') }
onMounted(loadAll)
</script>

<style scoped>
