:space-between;gap:20px}.section-title h2{margin:0 0 5px;color:var(--text-strong);font-size:22px}.section-title p{margin:0;color:var(--text-light);font-size:13px}.search-box{position:relative;display:flex;align-items:center;width:260px}.search-box>svg{position:absolute;left:13px;width:18px;color:#8ea0b9}.search-box input{width:100%;height:40px;padding:0 62px 0 39px;border:1px solid #dfe7f1;border-radius:10px;outline:0;color:var(--text-strong);font:inherit;font-size:13px;background:#fff}.search-box input:focus{border-color:#78a8ef;box-shadow:0 0 0 3px rgba(49,116,232,.08)}.search-box button{position:absolute;right:8px;padding:4px 6px;border:0;color:#8090a5;font-size:11px;background:none;cursor:pointer}.filter-row{display:flex;align-items:center;gap:8px;margin-bottom:20px}.filter-row button{padding:7px 13px;border:1px solid transparent;border-radius:8px;color:#8593a7;font:inherit;font-size:12px;background:transparent;cursor:pointer}.filter-row button.selected{border-color:#d6e4fa;color:var(--primary);font-weight:650;background:#edf4ff}.filter-row .refresh-button{display:inline-flex;margin-left:auto;align-items:center;gap:5px;color:#7b8ba1}.refresh-button svg{width:15px;height:15px}.refresh-button:disabled{cursor:wait;opacity:.55}.page-error{margin:0 0 18px;padding:11px 13px;border-radius:9px;color:#b44d4d;font-size:13px;background:#fff2f2}.page-error button{margin-left:8px;padding:0;border:0;color:#c33f3f;text-decoration:underline;background:none;cursor:pointer}.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.product-card{overflow:hidden;border:1px solid #e7edf5;border-radius:16px;background:#fff;box-shadow:0 5px 15px rgba(37,67,108,.03);cursor:pointer;transition:transform .2s,box-shadow .2s}.product-card:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(37,67,108,.1)}.product-image{position:relative;display:grid;height:184px;place-items:center;overflow:hidden;background:linear-gradient(145deg,#edf5ff,#dfeeff)}.product-image img{width:100%;height:100%;object-fit:cover}.product-image>span:not(.activity-badge){font-size:45px;filter:drop-shadow(0 8px 12px rgba(47,114,231,.15))}.activity-badge{position:absolute;top:12px;left:12px;padding:5px 8px;border-radius:6px;color:#2864c7;font-size:11px;background:rgba(255,255,255,.86)}.product-body{padding:16px}.product-body h3{overflow:hidden;margin:0 0 7px;color:#2b3b55;font-size:15px;text-overflow:ellipsis;white-space:nowrap}.product-body p{height:34px;overflow:hidden;margin:0 0 14px;color:#9aa8ba;font-size:12px;line-height:1.5}.price-row{display:flex;align-items:baseline;gap:7px}.price-row strong{color:#ee5e64;font-size:21px}.price-row del{color:#aeb8c6;font-size:11px}.stock{margin-left:auto;color:#9caabd;font-size:11px}.product-body>button{display:flex;width:100%;height:35px;margin-top:15px;align-items:center;justify-content:center;gap:5px;border:1px solid #d5e3f8;border-radius:8px;color:var(--primary);font:inherit;font-size:12px;font-weight:650;background:#f5f9ff;cursor:pointer}.product-body>button:hover{color:#fff;background:var(--primary)}.product-body>button svg{width:15px;height:15px}.empty-card{padding:65px 24px;border:1px solid #e7edf5;border-radius:18px;text-align:center;background:#fff}.empty-icon{display:grid;width:60px;height:60px;margin:0 auto 18px;place-items:center;border-radius:18px;font-size:27px;background:var(--primary-soft)}.empty-card h3{margin:0 0 9px;color:#34425a;font-size:17px}.empty-card p{margin:0;color:var(--text-light);font-size:13px}.skeleton{padding-bottom:18px}.skeleton-image{height:184px;background:linear-gradient(100deg,#edf2f8 30%,#f8fafc 45%,#edf2f8 60%);background-size:200% 100%;animation:shine 1.4s infinite}.skeleton-line{width:45%;height:12px;margin:14px 16px 0;border-radius:5px;background:#edf2f8}.skeleton-line.wide{width:72%;margin-top:18px}@keyframes shine{to{background-position:-200% 0}}@media(max-width:900px){.product-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){nav{display:none}.topbar{padding:0 18px}.user-area>span:not(.avatar){display:none}.content{padding:24px 16px}.hero-card{padding:34px 28px}.hero-mark{display:none}.toolbar{display:block;margin-top:30px}.search-box{width:100%;margin-top:18px}.filter-row{overflow:auto}.filter-row button{white-space:nowrap}.product-grid{gap:12px}.product-image{height:145px}.product-body{padding:13px}.product-body h3{font-size:14px}.price-row strong{font-size:18px}}@media(max-width:410px){.product-grid{grid-template-columns:1fr}.product-image{height:190px}}
</style>
